import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { DrillDownTable } from 'components/DrillDownTable';
import { ContentCardWithBreadcrumb } from 'pages/pillars/ValueCreation/CommercialResults/components/ContentCardWithBreadcrumb';
import { WaterfallSection } from 'pages/pillars/ValueCreation/CommercialResults/components/Sections/Charts/WaterfallSection/WaterfallSection';
import { UseWaterfallData } from 'pages/pillars/ValueCreation/CommercialResults/types';
import { volumeWaterfallConfig } from 'pages/pillars/ValueCreation/PerformanceTool/config';

import { watchTowerWaterfallMock } from '../../../__mocks__/WatchTowerWaterfall';
import { useWatchTowerDrillDownTable } from '../../../hooks/useWatchTowerDrillDownTable';
import {
  StyledContributionContent,
  StyledCountryChip,
  StyledStickyHeaderScope,
} from './ContributionSection.styles';

export const ContributionSection: React.FC = () => {
  const { formatMessage } = useIntl();

  const measure = formatMessage({
    id: 'ValueCreation.WatchTower.measure',
    defaultMessage: '[ k hl ]',
  });

  const waterfallData = useMemo<UseWaterfallData>(
    () => ({
      waterfallData: watchTowerWaterfallMock,
      title: formatMessage({
        id: 'ValueCreation.WatchTower.waterfall.title',
        defaultMessage: 'Waterfall',
      }),
      tooltip: formatMessage({
        id: 'ValueCreation.WatchTower.waterfall.tooltip',
        defaultMessage:
          'Volume change broken down by brand contribution, ranked by descending delta. Click a bar to drill down.',
      }),
      loading: false,
      error: null,
      waterfallVariant: 'large',
    }),
    [formatMessage],
  );

  const {
    rows,
    columnGroups,
    expandedIds,
    onToggleRow,
    compareChecked,
    onCompareChange,
    compareTooltip,
  } = useWatchTowerDrillDownTable();

  return (
    <StyledStickyHeaderScope>
      <ContentCardWithBreadcrumb
        title={formatMessage({
          id: 'ValueCreation.WatchTower.contribution.title',
          defaultMessage: 'Contribution',
        })}
        measure={measure}
        dataTestId="watch-tower-contribution-section"
        breadcrumb={
          <StyledCountryChip data-testid="watch-tower-country-chip">
            {formatMessage({
              id: 'ValueCreation.WatchTower.breadcrumb.country',
              defaultMessage: 'Brazil',
            })}
          </StyledCountryChip>
        }
      >
        <StyledContributionContent>
          <WaterfallSection
            config={volumeWaterfallConfig}
            title={waterfallData.title}
            tooltip={waterfallData.tooltip}
            measure={measure}
            data={waterfallData.waterfallData}
            loading={waterfallData.loading}
            error={waterfallData.error}
          />
          <DrillDownTable
            title={formatMessage({
              id: 'ValueCreation.WatchTower.table.title',
              defaultMessage: 'Table',
            })}
            unit={measure}
            columnGroups={columnGroups}
            rows={rows}
            expandedIds={expandedIds}
            onToggleRow={onToggleRow}
            compareLabel={formatMessage({
              id: 'ValueCreation.WatchTower.table.compareLabel',
              defaultMessage: 'Compare Efficiencies',
            })}
            compareTooltip={compareTooltip}
            compareChecked={compareChecked}
            onCompareChange={onCompareChange}
            dataTestId="watch-tower-drill-down-table"
          />
        </StyledContributionContent>
      </ContentCardWithBreadcrumb>
    </StyledStickyHeaderScope>
  );
};
